/*
 * A046446  Nonprimes whose prime factors contain only odd digits.
 * https://oeis.org/A046446
 *
 * Offset:    1    (a(1) is the first term)
 * Keywords:  nonn, easy, base
 * Formula:   not stated
 * Range:     u8 n <= 58, u16 n <= 58, u32 n <= 58, u64 n <= 58, u128 n <= 58,
 *            big any n
 * Helpers:   build_primes, odd_digit_prime
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

/* This function returns the nth nonprime whose prime factors are all odd‑digit primes. The sequence is generated by testing successive integers, factorising them by trial division using a growing list of primes, and storing those that satisfy the property. */

#include <stdint.h>
#include <stdlib.h>
#include <stdbool.h>
#include <string.h>

#include "../utils/build_primes.h"   /* build_primes(idx_t limit, idx_t **primes_out, size_t *cnt); */
#include "../utils/odd_digit_prime.h"

/* Cached terms (1‑based index). */
static seq_t *term_cache = NULL;
static size_t cache_cap  = 0;
static size_t cache_len  = 0;

/* Last value that has been examined (for sequential generation). */
static uint64_t last_value = 0;

/* Cached prime list for trial division. */
static uint64_t *prime_list = NULL;
static size_t   prime_cnt  = 0;
static idx_t    prime_limit = 0;

/* Ensure primes are known up to 'limit' (inclusive). */
static void ensure_primes_up_to(idx_t limit)
{
    if (limit <= prime_limit)
        return;
    uint64_t *new_primes = NULL;
    size_t   new_cnt     = 0;
    build_primes(limit, &new_primes, &new_cnt);
    if (prime_list) free(prime_list);
    prime_list = new_primes;
    prime_cnt  = new_cnt;
    prime_limit = limit;
}

/* Integer square root for uint64_t (floor). */
static idx_t isqrt_u64(idx_t n)
{
    idx_t low = 0, high = n;
    while (low <= high) {
        idx_t mid = low + ((high - low) >> 1);
        idx_t sq  = mid * mid;
        if (sq == n)
            return mid;
        if (sq < n)
            low = mid + 1;
        else
            high = mid - 1;
    }
    return high;
}

/* Test whether 'n' is a member of the sequence. */
static bool is_seq_term(uint64_t n)
{
    if (n == 1)
        return true;
    uint64_t temp = n;
    bool found_factor = false;
    /* Ensure we have enough primes for factoring. */
    ensure_primes_up_to(isqrt_u64(n));
    size_t i = 0;
    while (i < prime_cnt && prime_list[i] * prime_list[i] <= temp) {
        uint64_t p = prime_list[i];
        if (temp % p == 0) {
            found_factor = true;
            if (!odd_digit_prime(p))
                return false;
            while (temp % p == 0)
                temp /= p;
        }
        ++i;
    }
    if (!found_factor)          /* n is prime */
        return false;
    if (temp > 1) {              /* remaining prime factor > sqrt(n) */
        if (!odd_digit_prime(temp))
            return false;
    }
    return true;
}

/* Fill cache up to 'n' terms. */
static void fill_until(idx_t n)
{
    if (cache_len >= (size_t)n)
        return;
    /* Grow cache if needed. */
    if (cache_cap == 0) {
        cache_cap = 64;
        term_cache = (seq_t *)malloc(cache_cap * sizeof(seq_t));
    }

    while (cache_len < (size_t)n) {
        uint64_t current = last_value + 1;  /* next integer to test */
        if (is_seq_term(current)) {
            if (cache_len == cache_cap) {
                cache_cap *= 2;
                term_cache = (seq_t *)realloc(term_cache, cache_cap * sizeof(seq_t));
            }
            term_cache[cache_len++] = (seq_t)current;
        }
        last_value = current;
    }
}

seq_t a(idx_t n)
{
    /* Convert idx_t to size_t safely for internal use. */
    size_t idx = (size_t)n;
    if (idx == 0)
        return (seq_t)0;   /* undefined behaviour for n < 1 */
    fill_until(idx);
    return term_cache[idx - 1];
}
